<?php
namespace App\Entity;
use App\Repository\CatalogSourceRepository;
use Doctrine\ORM\Mapping as ORM;
#[ORM\Entity(repositoryClass:CatalogSourceRepository::class)]
#[ORM\UniqueConstraint(name:'uniq_catalog_source',columns:['provider','external_id'])]
class CatalogSource { #[ORM\Id,ORM\GeneratedValue,ORM\Column] private ?int $id=null; #[ORM\Column(length:40)] private string $provider; #[ORM\Column(name:'external_id',length:100)] private string $externalId; #[ORM\ManyToOne] #[ORM\JoinColumn(nullable:false,onDelete:'CASCADE')] private Series $series; #[ORM\Column(type:'json')] private array $payload=[]; #[ORM\Column] private \DateTimeImmutable $fetchedAt; #[ORM\Column] private \DateTimeImmutable $expiresAt; public function __construct(string $provider,string $externalId,Series $series){$this->provider=$provider;$this->externalId=$externalId;$this->series=$series;$this->fetchedAt=new \DateTimeImmutable();$this->expiresAt=$this->fetchedAt;} public function getSeries():Series{return $this->series;} public function getProvider():string{return $this->provider;} public function getExternalId():string{return $this->externalId;} public function getPayload():array{return $this->payload;} public function isFresh():bool{return $this->expiresAt>new \DateTimeImmutable();} public function refresh(array $payload,\DateTimeImmutable $expiresAt):void{$this->payload=$payload;$this->fetchedAt=new \DateTimeImmutable();$this->expiresAt=$expiresAt;} }
